namespace RonSijm.FluidHumidifier.Factories.CloudFront;

public class DistributionTenantFactory(string resourceName = null, Action<Humidifier.CloudFront.DistributionTenant> factoryAction = null) : ResourceFactory<Humidifier.CloudFront.DistributionTenant>(resourceName)
{

    internal List<InnerDistributionTenantParameterFactory> ParametersFactories { get; set; } = [];

    internal InnerDistributionTenantCustomizationsFactory CustomizationsFactory { get; set; }

    internal InnerDistributionTenantManagedCertificateRequestFactory ManagedCertificateRequestFactory { get; set; }

    protected override Humidifier.CloudFront.DistributionTenant Create()
    {
        var distributionTenantResult = CreateDistributionTenant();
        factoryAction?.Invoke(distributionTenantResult);

        return distributionTenantResult;
    }

    private Humidifier.CloudFront.DistributionTenant CreateDistributionTenant()
    {
        var distributionTenantResult = new Humidifier.CloudFront.DistributionTenant
        {
            GivenName = InputResourceName,
        };

        return distributionTenantResult;
    }
    public override void CreateChildren(Humidifier.CloudFront.DistributionTenant result)
    {
        base.CreateChildren(result);

        result.Parameters = ParametersFactories.Any() ? ParametersFactories.Select(x => x.Build()).ToList() : null;
        result.Customizations ??= CustomizationsFactory?.Build();
        result.ManagedCertificateRequest ??= ManagedCertificateRequestFactory?.Build();
    }

} // End Of Class

